import{_ as e,o as a,c as d,aj as r}from"./framework.js";const p=JSON.parse('{"title":"创建第一个站点 | Quick Start | Documentation","description":"创建第一个站点 in Kooboo: 登录后会进入站点列表。这里是账户级页面，不带 SiteId。如果你已经有站点，点击站点卡片上的 管理 进入站点后台。","frontmatter":{"title":"创建第一个站点 | Quick Start | Documentation","description":"创建第一个站点 in Kooboo: 登录后会进入站点列表。这里是账户级页面，不带 SiteId。如果你已经有站点，点击站点卡片上的 管理 进入站点后台。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/quick-start/create-first-site.html"}]]},"headers":[],"relativePath":"zh/quick-start/create-first-site.md","filePath":"quick-start/create-first-site.md","lastUpdated":1780991406000}'),o={name:"zh/quick-start/create-first-site.md"};function i(s,t,c,h,n,l){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="创建第一个站点" tabindex="-1">创建第一个站点 <a class="header-anchor" href="#创建第一个站点" aria-label="Permalink to &quot;创建第一个站点&quot;">​</a></h1><blockquote><p>从登录后台到进入站点管理页。</p></blockquote><h2 id="登录并确认入口" tabindex="-1">登录并确认入口 <a class="header-anchor" href="#登录并确认入口" aria-label="Permalink to &quot;登录并确认入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>后台入口</td><td><code>/_Admin/</code></td></tr><tr><td>旧路径兼容</td><td><code>/_Admin/Sites</code> 会回到站点列表</td></tr><tr><td>主要页面</td><td>站点列表、文件夹、新建站点</td></tr></tbody></table><p>登录后会进入站点列表。这里是账户级页面，不带 <code>SiteId</code>。如果你已经有站点，点击站点卡片上的 <strong>管理</strong> 进入站点后台。</p><h2 id="新建站点" tabindex="-1">新建站点 <a class="header-anchor" href="#新建站点" aria-label="Permalink to &quot;新建站点&quot;">​</a></h2><p>后台提供三种常用方式：</p><table tabindex="0"><thead><tr><th>方式</th><th>深链</th><th>适合场景</th></tr></thead><tbody><tr><td>空白站点</td><td><code>/_Admin/create</code></td><td>想从最小结构开始</td></tr><tr><td>导入站点</td><td><code>/_Admin/create/import</code></td><td>已有站点包、ZIP 或迁移来源</td></tr><tr><td>克隆站点</td><td><code>/_Admin/create/clone</code></td><td>复制已有站点作为新项目起点</td></tr></tbody></table><p>如果你想从模板开始，也可以先打开 <a href="/kb-docs/zh/product/market.html">市场</a>，选择模板后再创建站点。</p><h2 id="第一次进入站点后台" tabindex="-1">第一次进入站点后台 <a class="header-anchor" href="#第一次进入站点后台" aria-label="Permalink to &quot;第一次进入站点后台&quot;">​</a></h2><p>进入站点后台后，URL 通常会带上站点 ID：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/_Admin/site/dashboard?SiteId={站点GUID}</span></span></code></pre></div><p>后续 CMS 文档里的站点级深链都会使用同样格式。你可以把 <code>{站点GUID}</code> 替换成当前站点地址栏里的 <code>SiteId</code>。</p><h2 id="建议先确认" tabindex="-1">建议先确认 <a class="header-anchor" href="#建议先确认" aria-label="Permalink to &quot;建议先确认&quot;">​</a></h2><table tabindex="0"><thead><tr><th>检查项</th><th>位置</th></tr></thead><tbody><tr><td>站点名称、默认语言、Base URL</td><td><a href="/kb-docs/zh/cms/settings/basic/general.html">基础设置</a></td></tr><tr><td>是否需要多语言</td><td><a href="/kb-docs/zh/cms/settings/basic/general.html">基础设置：基础</a> 与 <a href="/kb-docs/zh/cms/development/spa-multilingual.html">SPA 多语言</a></td></tr><tr><td>是否需要团队协作</td><td><a href="/kb-docs/zh/cms/settings/site-users.html">站点用户</a> 与 <a href="/kb-docs/zh/cms/settings/roles.html">角色权限</a></td></tr><tr><td>是否需要 AI 能力</td><td><a href="/kb-docs/zh/cms/settings/ai-service.html">AI 服务</a></td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>继续 <a href="./build-first-page.html">做第一个页面</a>。</p>',17)])])}const m=e(o,[["render",i]]);export{p as __pageData,m as default};
